// ============================================
// RUNTIME-MODIFIABLE WEAPON INSTANCE
// ============================================
public class WeaponInstance
{
    public WeaponData BaseData { get; private set; }

    // Runtime-modified stats
    public int CurrentAmmo { get; set; }
    public int CurrentMagazineSize { get; set; }
    public float CurrentDamage { get; set; }
    public int UpgradeLevel { get; set; }

    // Runtime state
    public float CurrentSpread { get; private set; }
    public float CurrentRecoil { get; private set; }
    public bool IsReloading { get; private set; }
    public float LastFireTime { get; private set; }

    public WeaponInstance(WeaponData baseData)
    {
        BaseData = baseData;
        ResetToBaseStats();
    }

    public void ResetToBaseStats()
    {
        CurrentAmmo = BaseData.magazineSize;
        CurrentMagazineSize = BaseData.magazineSize;
        CurrentDamage = BaseData.damage;
        CurrentSpread = BaseData.baseSpread;
        CurrentRecoil = 0f;
        UpgradeLevel = 0;
    }

    public void Upgrade()
    {
        UpgradeLevel++;
        CurrentDamage *= 1.2f;
        CurrentMagazineSize = Mathf.RoundToInt(BaseData.magazineSize * (1 + UpgradeLevel * 0.1f));
        CurrentAmmo = CurrentMagazineSize;
    }

    public bool CanFire()
    {
        return !IsReloading && CurrentAmmo > 0 && 
               Time.time >= LastFireTime + BaseData.fireRate;
    }

    public void Fire()
    {
        if (!CanFire()) return;

        CurrentAmmo--;
        LastFireTime = Time.time;

        // Increase spread with each shot
        CurrentSpread = Mathf.Min(
            CurrentSpread + BaseData.spreadPerShot,
            BaseData.maxSpread
        );

        // Apply recoil
        CurrentRecoil = BaseData.verticalRecoil.Evaluate(
            1f - (float)CurrentAmmo / CurrentMagazineSize
        );
    }

    public void RecoverSpread(float deltaTime)
    {
        CurrentSpread = Mathf.Max(
            BaseData.baseSpread,
            CurrentSpread - BaseData.spreadRecovery * deltaTime
        );
        CurrentRecoil = Mathf.Max(0f, CurrentRecoil - BaseData.recoilRecoverySpeed * deltaTime);
    }

    public void StartReload()
    {
        if (IsReloading || CurrentAmmo == CurrentMagazineSize) return;
        IsReloading = true;
    }

    public void FinishReload()
    {
        CurrentAmmo = CurrentMagazineSize;
        IsReloading = false;
        CurrentSpread = BaseData.baseSpread;
    }
}

// ============================================
// INVENTORY SYSTEM USING RUNTIME INSTANCES
// ============================================
public class Inventory : MonoBehaviour
{
    [SerializeField] private List<WeaponData> startingWeapons;
    private List<WeaponInstance> weapons = new();
    private int equippedWeaponIndex = -1;

    void Start()
    {
        foreach (var data in startingWeapons)
        {
            AddWeapon(data);
        }

        if (weapons.Count > 0)
            EquipWeapon(0);
    }

    public WeaponInstance AddWeapon(WeaponData data)
    {
        var instance = new WeaponInstance(data);
        weapons.Add(instance);
        return instance;
    }

    public void EquipWeapon(int index)
    {
        if (index < 0 || index >= weapons.Count) return;
        equippedWeaponIndex = index;

        var weapon = GetEquippedWeapon();
        // Spawn visual model, configure UI, etc.
        Debug.Log($"Equipped: {weapon.BaseData.weaponName}");
    }

    public WeaponInstance GetEquippedWeapon()
    {
        return equippedWeaponIndex >= 0 ? weapons[equippedWeaponIndex] : null;
    }

    public void UpgradeEquippedWeapon()
    {
        var weapon = GetEquippedWeapon();
        if (weapon == null) return;

        int cost = weapon.BaseData.upgradeCost * (weapon.UpgradeLevel + 1);
        if (GameState.Instance.SpendCurrency(cost))
        {
            weapon.Upgrade();
            Debug.Log($"Upgraded to level {weapon.UpgradeLevel}!");
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

// ============================================
// RUNTIME SET — tracks active objects of type T
// ============================================
public abstract class RuntimeSet<T> : ScriptableObject
{
    [SerializeField] private List<T> items = new();

    public int Count => items.Count;
    public T this[int index] => items[index];

    public void Add(T item)
    {
        if (!items.Contains(item))
            items.Add(item);
    }

    public void Remove(T item)
    {
        if (items.Contains(item))
            items.Remove(item);
    }

    public void Clear() => items.Clear();

    public T GetRandom() => items.Count > 0 ? items[Random.Range(0, items.Count)] : default;
    public T GetNearest(Vector3 position)
    {
        T nearest = default;
        float nearestDist = float.MaxValue;

        foreach (var item in items)
        {
            // Assumes T has a transform — use interface in real code
            var mono = item as MonoBehaviour;
            if (mono == null) continue;

            float dist = Vector3.Distance(position, mono.transform.position);
            if (dist < nearestDist)
            {
                nearestDist = dist;
                nearest = item;
            }
        }

        return nearest;
    }
}

