// ============================================
[CreateAssetMenu(menuName = "Game/Events/Void Event")]
public class GameEventSO : ScriptableObject
{
    private readonly List<GameEventListener> listeners = new();

    public void Raise()
    {
        // Iterate backwards so listeners can remove themselves during iteration
        for (int i = listeners.Count - 1; i >= 0; i--)
        {
            listeners[i].OnEventRaised();
        }
    }

    public void RegisterListener(GameEventListener listener)
    {
        if (!listeners.Contains(listener))
            listeners.Add(listener);
    }

    public void UnregisterListener(GameEventListener listener)
    {
        if (listeners.Contains(listener))
            listeners.Remove(listener);
    }
}

// MonoBehaviour that listens to a GameEventSO — drag in Inspector
public class GameEventListener : MonoBehaviour
{
    [SerializeField] private GameEventSO gameEvent;
    [SerializeField] private UnityEngine.Events.UnityEvent response;

    void OnEnable() => gameEvent?.RegisterListener(this);
    void OnDisable() => gameEvent?.UnregisterListener(this);

    public void OnEventRaised() => response?.Invoke();
}

